parameters.jsCode:
// 4.3.3.1 (part 1) - Validate + normalize the merged reply signal
const item = $input.item.json;

const errors = [];
if (!item.client_id && !item.email) errors.push('client_id or email required');
if (!item.channel) errors.push('channel required');
if (!['email','whatsapp','linkedin'].includes((item.channel||'').toLowerCase())) errors.push('channel must be email|whatsapp|linkedin');
if (!item.occurred_at) errors.push('occurred_at required');

const normalized = {
  client_id: item.client_id || null,
  email: item.email ? String(item.email).trim().toLowerCase() : null,
  channel: item.channel ? String(item.channel).trim().toLowerCase() : null,
  reply_content: item.reply_content || '',
  occurred_at: item.occurred_at || new Date().toISOString(),
  workflow_source: item.workflow_source || 'unknown',
  is_valid: errors.length === 0,
  validation_errors: errors.join('; ')
};

return [{ json: normalized }];

parameters.query:
-- 4.3.3.1 (part 2) - resolve client_id from email when only email was supplied (LinkedIn/Waha payloads may not carry client_id)
SELECT id AS client_id FROM clients_master
WHERE id = {{ $json.client_id ? $json.client_id : 'NULL' }}
   OR email = {{ $json.email ? `'${$json.email}'` : 'NULL' }}
LIMIT 1;

-- 4.3.3.1 (part 3) - write the event to history (per §16.5 canonical event table)
INSERT INTO communication_events (client_id, channel, direction, content, occurred_at, workflow_source)
VALUES (
  {{ $json.client_id }},
  {{ JSON.stringify($('Validate & Normalize Reply Signal').item.json.channel) }},
  'inbound',
  {{ JSON.stringify($('Validate & Normalize Reply Signal').item.json.reply_content) }},
  {{ JSON.stringify($('Validate & Normalize Reply Signal').item.json.occurred_at) }}::timestamp,
  {{ JSON.stringify($('Validate & Normalize Reply Signal').item.json.workflow_source) }}
);

-- No matching client_id/email in clients_master - log for manual review, do not silently drop
INSERT INTO workflow_errors (workflow_name, execution_id, node_name, error_message, input_payload)
VALUES ('4.3.3 - Unified Reply Merge + Nurture Suppression', '{{ $execution.id }}', 'Client Found?', 'No matching client_id/email in clients_master', {{ JSON.stringify($json) }}::jsonb);
